import { SpriteNodeMaterial, texture, uv, vec4 } from 'three/tsl';
import * as THREE from 'three/webgpu';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'pricing-card-1-sprite';
  group.position.set(-3.2, -0.3, 0);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const atlasTex = ctx.textureLoader.load('/prism-mock/home/nodes/floating-accent.png');
  atlasTex.colorSpace = THREE.SRGBColorSpace;

  const rect = { x: 0, y: 0, w: 512, h: 320, atlasW: 512, atlasH: 320 };
  const aspect = rect.w / rect.h;

  const width = 1.6;
  const height = width / aspect;

  const geometry = new THREE.PlaneGeometry(width, height);

  const uOffset = rect.x / rect.atlasW;
  const vOffset = 1 - (rect.y + rect.h) / rect.atlasH;
  const uScale = rect.w / rect.atlasW;
  const vScale = rect.h / rect.atlasH;

  const uvNode = uv().mul([uScale, vScale]).add([uOffset, vOffset]);
  const mapNode = texture(atlasTex, uvNode);

  const material = new SpriteNodeMaterial({ transparent: true });
  material.colorNode = mapNode;
  material.opacityNode = vec4(mapNode).a;

  const sprite = new THREE.Sprite(material);
  sprite.scale.set(width, height, 1);
  sprite.name = 'pricing-card-1-sprite-mesh';

  group.add(sprite);

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    material.dispose();
    if (atlasTex) atlasTex.dispose();
    geometry.dispose();
  };

  return group;
}
